float3 along=dot(d,dir)*dir;
return (d-along)*(fx-1.0)+along*(fy-1.0);

material.shader:
// M_Decal_MP: operation order from the compiled decal pixel shader; see prepare_attack.decal_definition().
float2 uvE=UV-0.5;
uvE=float2(dot(uvE,float2(1.0,-0.0)),dot(uvE,float2(0.0,1.0)))+0.5;
uvE=uvE*float2(1.0,1.0);
uvE=lerp(uvE,saturate(uvE),1.0);
float4 te=Texture2DSample(TexEmissive,TexEmissiveSampler,uvE);
float3 e=lerp(te.rgb,dot(te,float4(1.0,0.0,0.0,0.0)).xxx,1.0);
float3 p=step(1e-6,e)*pow(max(e,1e-6),1.0)*1.0;
float3 col=lerp(p,e*2.0,0.5)*Emissive_ColorTint.rgb*5.0;
float2 uvM=UV-0.5;
uvM=float2(dot(uvM,float2(1.0,-0.0)),dot(uvM,float2(0.0,1.0)))+0.5;
uvM=uvM*float2(1.0,1.0);
uvM=lerp(uvM,saturate(uvM),0.0);
float m=dot(Texture2DSample(TexMask,TexMaskSampler,uvM),float4(0.0,1.0,0.0,0.0))*5.0;
float2 uvB=UV-0.5;
uvB=float2(dot(uvB,float2(1.0,-0.0)),dot(uvB,float2(0.0,1.0)))+0.5;
uvB=uvB*float2(1.0,1.0);
uvB=lerp(uvB,saturate(uvB),0.0);
float b=dot(Texture2DSample(TexBase,TexBaseSampler,uvB),float4(0.0,0.0,0.0,1.0))*Base_Alpha_Multiply;
float2 uvD=UV-0.5;
uvD=float2(dot(uvD,float2(6.123234e-17,-1.0)),dot(uvD,float2(1.0,6.123234e-17)))+0.5;
uvD=uvD*float2(1.0,1.0);
uvD=lerp(uvD,saturate(uvD),0.0);
float d=dot(Texture2DSample(TexDissolve,TexDissolveSampler,uvD),float4(1.0,0.0,0.0,0.0));
float S=5.0;
float erosion=saturate(S*(d-1.0)+Dissolve_Dissolve*(S+1.0));
float z=abs(DecalPos.z*2.0-1.0);
float fade=pow(saturate(1.0-z),max(ZFadingPower,1e-3));
return float4(max(col,0.0),saturate(m*b*erosion*fade));

// M_GhostNew (UseDither): operation order from the compiled pixel shader; see prepare_attack.ghost_definition().
float f=1.0-saturate(dot(normalize(N),normalize(V)));
float3 rim=step(1e-6,f)*pow(max(f,1e-6),RimWidth)*RimScale*RimColor.rgb;
float3 col=max(Color.rgb+rim,0.0);
int2 px=int2(floor(Parameters.SvPosition.xy-ResolvedView.ViewRectMin.xy));
const float dither[9]={0.0,0.777778,0.333333,0.666667,0.555556,0.222222,0.444444,0.111111,0.888889};
float d=dither[(abs(px.x)%3)*3+abs(px.y)%3];
float a=saturate(2.0*(Fade*Color.a+DitherOffset)-d);
return float4(col*a,a);
